//! 保留 Go 版 Lyra 与 Canto 读取凭据文件和客户端文件时的取值语义. 这些文件由
//! 运维脚本手写或生成, 字段类型并不严格, 因此判断规则必须与原实现一致, 否则同一份
//! 文件在新旧版本中会启用不同的账号.
//!
//! Preserves the value semantics the Go Lyra and Canto used for credential and client
//! files. These files are hand-written or generated by scripts with loose field types,
//! so the rules must match the original or one file would enable different accounts.

use serde_json::Value;

/// 历史上 enabled 字段的真值规则: null, 空字符串, 空数组, 空对象, false 与数值 0
/// 为假, 其余为真. 注意字符串 "false" 为真, 这是 Python 原实现留下的行为.
///
/// Truthiness of the historical enabled field: null, empty string, empty array, empty
/// object, false and numeric zero are false; everything else is true. The string
/// "false" is true, a behavior inherited from the original Python implementation.
pub fn truthy(value: &Value) -> bool {
    match value {
        Value::Null => false,
        Value::Bool(flag) => *flag,
        Value::String(text) => !text.is_empty(),
        Value::Number(number) => number.as_f64().is_some_and(|n| n != 0.0),
        Value::Array(items) => !items.is_empty(),
        Value::Object(fields) => !fields.is_empty(),
    }
}

/// 只接受 JSON 整数. 5.0 与 "5" 都返回 None, 对应 Go 的 IntStrict.
///
/// Accepts only JSON integers; 5.0 and "5" return None, matching Go's IntStrict.
pub fn int_strict(value: &Value) -> Option<i64> {
    match value {
        Value::Number(number) => number.as_i64(),
        _ => None,
    }
}

/// 接受 JSON 整数, 也接受浮点数并向零截断, 对应 Go 的 IntLoose. 超出 i64 的浮点数
/// 按 Rust 的饱和转换处理.
///
/// Accepts JSON integers and truncates floats toward zero, matching Go's IntLoose.
/// Floats outside i64 saturate, which is Rust's conversion rule.
pub fn int_loose(value: &Value) -> Option<i64> {
    match value {
        Value::Number(number) => number
            .as_i64()
            .or_else(|| number.as_f64().map(|float| float as i64)),
        _ => None,
    }
}

/// 只在取值是 JSON 字符串时返回内容.
///
/// Returns the content only when the value is a JSON string.
pub fn as_str(value: Option<&Value>) -> Option<&str> {
    value.and_then(Value::as_str)
}

/// 按 Go 的 fmt.Sprint 文本比较两个标量. 凭据池用它按 account_id 定位条目, 而该字段
/// 在不同来源中可能是字符串, 也可能是数字, 文本相同即视为同一账号.
///
/// Compares two scalars by their Go fmt.Sprint text. The credential pool locates an
/// entry by account_id, which may be a string or a number depending on its source;
/// equal text means the same account.
pub fn same_value(left: Option<&Value>, right: Option<&Value>) -> bool {
    sprint(left) == sprint(right)
}

fn sprint(value: Option<&Value>) -> String {
    match value {
        None | Some(Value::Null) => "<nil>".to_owned(),
        Some(Value::String(text)) => text.clone(),
        Some(other) => other.to_string(),
    }
}
